ting'=>'Aantal advertenties om te tonen als gerelateerde advertentie','px'=>'px','%'=>'%','Country code'=>'Landcode','State code'=>'Provinciecode','Rate&nbsp;%'=>'Tarief&nbsp;%','Tax name'=>'Belastingnaam','Priority'=>'Prioriteit','Insert row'=>'Rij invoegen','Remove selected row(s)'=>'Geselecteerde rij(en) verwijderen','Enable tax.'=>'Belasting inschakelen.','Select Parent'=>'Selecteer bovenliggende','Show only the immediate children of the selected category. Displays all the top level categories if no parent is selected.'=>'Toon alleen de directe subcategorieën van de geselecteerde categorie. Toont alle hoofdcategorieën als er geen bovenliggende is geselecteerd.','Show image of the Categories'=>'Afbeelding van categorieën tonen','Show icon of the Categories'=>'Pictogram van categorieën tonen','Hide Empty Categories'=>'Lege categorieën verbergen','Show Listing Counts'=>'Aantal advertenties tonen','All Location'=>'Alle locaties','Selected Location'=>'Geselecteerde locatie','Inline'=>'Inline','New Line'=>'Nieuwe regel','6 Col'=>'6 kolommen','4 Col'=>'4 kolommen','3 Col'=>'3 kolommen','2 Col'=>'2 kolommen','1 Col'=>'1 kolom','No posts found.'=>'Geen berichten gevonden.','Card Border Radius'=>'Randradius kaart','Enable translate card on hover'=>'Kaart optillen bij hover inschakelen','Lift the card slightly when the visitor hovers over it. Turning this off keeps the border and shadow hover effect.'=>'Til de kaart iets op wanneer de bezoeker eroverheen beweegt. Als je dit uitschakelt, blijft het hover-effect van rand en schaduw behouden.','Content'=>'Inhoud','Location Display Type'=>'Locatieweergavetype','Select Location'=>'Selecteer locatie','Location Limit'=>'Locatielimiet','Only Parent Location'=>'Alleen bovenliggende locatie','Sort By'=>'Sorteren op','Hide Empty'=>'Lege verbergen','Elements'=>'Elementen','Show Child location'=>'Sublocatie tonen','Sub Location Limit'=>'Sublocatielimiet','Show Counts'=>'Aantallen tonen','Count position'=>'Positie aantal','Enable Link'=